export const RosterSeat_set_brain_str = (m: Mem, p: number, v: string) => { cstrSet(m, p + 105, 24, v, 'RosterSeat.brain'); };
// Span
export const Span_SIZE = 8;
export const Span_off_at = (p: number) => p;
export const Span_get_off = (m: Mem, p: number) => m.dv.getInt32(p, true);
export const Span_set_off = (m: Mem, p: number, v: number) => { m.dv.setInt32(p, v, true); };
export const Span_len_at = (p: number) => p + 4;
export const Span_get_len = (m: Mem, p: number) => m.dv.getInt32(p + 4, true);
export const Span_set_len = (m: Mem, p: number, v: number) => { m.dv.setInt32(p + 4, v, true); };
